(()=>{const params=new URLSearchParams(location.search);const buttons=[...document.querySelectorAll('[data-layout]')];function setLayout(layout,update){const b=layout==='b';document.body.classList.toggle('layout-b',b);buttons.forEach(button=>button.setAttribute('aria-pressed',String(button.dataset.layout===layout)));document.getElementById('layout-status').textContent=b?'Option B · Editorial list':'Option A · Project cards';if(update){const url=new URL(location.href);url.searchParams.set('layout',layout);history.replaceState(null,'',url);}}buttons.forEach(button=>button.addEventListener('click',()=>setLayout(button.dataset.layout,true)));setLayout(params.get('layout')==='b'?'b':'a',false);})();